#!/usr/bin/env bash
# Generated by test-suite-generator/1.1.0
# based_on: REQ-001, REQ-002, REQ-003, REQ-004, REQ-005, REQ-006, REQ-007, REQ-008, REQ-009, REQ-010, REQ-011
#
# L5 runner for sdlc-ring-audit: existence.sh (fail-fast on its own) then the unittest suite, then ONE summary line.
# Both stages always run so the summary reports both; exit 1 if either failed.  (existence.sh itself stays fail-fast —
# the aggregation here is the runner's, not the existence script's.)  Mutation scoring is separate: mutation.sh.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$HERE/../../../../../.." && pwd)"
cd "$REPO"

EX="ok"
if ! bash "$HERE/existence.sh"; then EX="FAIL"; fi

UT="ok"
LOG="$(mktemp)"
if ! python3 -m unittest discover -s "$HERE" -p 'test_*.py' -v >"$LOG" 2>&1; then UT="FAIL"; fi
cat "$LOG"
RAN="$(grep -E '^Ran [0-9]+ tests?' "$LOG" || echo 'Ran 0 tests')"
VERDICT="$(grep -E '^(OK|FAILED)' "$LOG" | tail -1 || echo 'FAILED (no verdict line)')"
rm -f "$LOG"

echo "ring-audit L5: existence=$EX unittest=$UT | $RAN | $VERDICT | HEAD=$(git rev-parse --short HEAD)"
if [ "$EX" = "FAIL" ] || [ "$UT" = "FAIL" ]; then exit 1; fi
